<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{api,type ApiResponse,type Product,type Review,type Sku}from'@whaashop/shared';
interface Address{id:number;receiverName:string;phone:string;province:string;city:string;district:string;detail:string;isDefault:boolean}
const route=useRoute(),router=useRouter(),product=ref<Product>(),skus=ref<Sku[]>([]),selected=ref<number>(),quantity=ref(1),reviews=ref<Review[]>([]),stats=ref({total:0,average:0}),message=ref(''),addresses=ref<Address[]>([]),addressDialog=ref(false),addressLoading=ref(false),submitting=ref(false),selectedAddressId=ref<number>();const stars=computed(()=>Math.round(stats.value.average));const selectedSku=computed(()=>skus.value.find(v=>v.id===selected.value));const total=computed(()=>Number(selectedSku.value?.price??product.value?.minPrice??0)*quantity.value);
const labels:Record<string,string>={color:'颜色',size:'规格',switch:'轴体',storage:'容量',version:'版本'};function formatSpec(raw:string){try{const value=JSON.parse(raw)as Record<string,unknown>;return Object.entries(value).map(([k,v])=>`${labels[k]??k}：${String(v)}`).join(' · ')||'默认规格'}catch{return raw.replace(/[{}"']/g,'').replace(/:/g,'：').replace(/,/g,' · ')||'默认规格'}}function images(raw:string){try{return JSON.parse(raw)as string[]}catch{return[]}}function fullAddress(a:Address){return[a.province,a.city,a.district,a.detail].filter(Boolean).join(' ')}
onMounted(async()=>{const id=route.params.id;const[p,r,s]=await Promise.all([api.get<ApiResponse<{product:Product;skus:Sku[]}>>(`/shop/products/${id}`),api.get<ApiResponse<{items:Review[]}>>(`/shop/products/${id}/reviews`),api.get<ApiResponse<{total:number;average:number}>>(`/shop/products/${id}/review-stats`)]);product.value=p.data.data.product;skus.value=p.data.data.skus;selected.value=skus.value.find(v=>v.stock>0)?.id;reviews.value=r.data.data.items;stats.value=s.data.data});
async function add(){if(!localStorage.getItem('token'))return router.push('/login');if(!selected.value)return message.value='请选择商品规格';await api.post('/shop/cart',{skuId:selected.value,quantity:quantity.value});message.value='✓ 已加入购物车'}
async function openBuyNow(){message.value='';if(!localStorage.getItem('token'))return router.push('/login');if(!selected.value)return message.value='请选择有库存的商品规格';quantity.value=Math.max(1,Math.min(selectedSku.value?.stock??1,quantity.value));addressDialog.value=true;addressLoading.value=true;try{addresses.value=(await api.get<ApiResponse<Address[]>>('/shop/addresses')).data.data;selectedAddressId.value=addresses.value.find(a=>a.isDefault)?.id??addresses.value[0]?.id}catch(e){message.value=(e as Error).message}finally{addressLoading.value=false}}
async function buyNow(){const address=addresses.value.find(a=>a.id===selectedAddressId.value);if(!address||!selected.value)return;submitting.value=true;try{await api.post('/shop/orders/buy-now',{skuId:selected.value,quantity:quantity.value,receiverName:address.receiverName,receiverPhone:address.phone,receiverAddress:fullAddress(address)});addressDialog.value=false;router.push('/orders')}catch(e){message.value=(e as Error).message}finally{submitting.value=false}}
</script>
<template><div v-if="product" class="container product-page"><div class="breadcrumb"><router-link to="/">首页</router-link><span>/</span><span>商品详情</span><span>/</span><b>{{product.name}}</b></div><section class="detail detail-card"><div class="gallery"><span class="image-badge">品质精选</span><img :src="product.mainImage" :alt="product.name"><div class="image-dots"><i></i><i></i><i></i></div></div><div class="buy-box"><span class="eyebrow">QUALITY SELECTION</span><h1>{{product.name}}</h1><p class="subtitle">{{product.subtitle}}</p><div class="rating-line"><span class="stars">★★★★★</span><b>{{stats.average||'新品'}}</b><span>{{stats.total}} 条评价</span><span>{{product.sales}} 人已购</span></div><div class="sale-price"><small>商城价</small><strong>¥{{selectedSku?.price??product.minPrice}}</strong><span>限时好价</span></div><div class="benefits"><span>✓ 正品保障</span><span>✓ 安全支付</span><span>✓ 智能客服</span></div><div class="choice"><b>选择规格</b><div class="spec-list"><label v-for="s in skus" :key="s.id" :class="{active:selected===s.id,disabled:s.stock===0}"><input v-model="selected" type="radio" :value="s.id" :disabled="s.stock===0"><span>{{formatSpec(s.specJson)}}</span><small>库存 {{s.stock}}</small></label></div></div><div class="purchase-row"><div class="quantity"><button @click="quantity=Math.max(1,quantity-1)">−</button><input v-model.number="quantity" type="number" min="1" :max="selectedSku?.stock"><button @click="quantity=Math.min(selectedSku?.stock??99,quantity+1)">＋</button></div><button class="btn add-btn" @click="add">加入购物车</button><button class="buy-now" @click="openBuyNow">立即购买</button></div><p v-if="message" class="success-message">{{message}}</p></div></section><section class="panel content-panel"><div class="section-tabs"><b>商品详情</b><a href="#reviews">用户评价（{{stats.total}}）</a></div><div class="rich" v-html="product.detailHtml"></div></section><section id="reviews" class="panel review-panel"><div class="review-summary"><div><strong>{{stats.average.toFixed(1)}}</strong><span class="stars">{{'★'.repeat(stars)}}{{'☆'.repeat(5-stars)}}</span><small>综合评分</small></div><div><h2>真实用户评价</h2><p class="muted">每一条评价都来自确认收货后的真实购买体验</p></div></div><article v-for="r in reviews" :key="r.id" class="review review-card"><div class="review-avatar">用</div><div><div class="stars">{{'★'.repeat(r.rating)}}{{'☆'.repeat(5-r.rating)}}</div><p>{{r.content}}</p><div v-if="images(r.imagesJson).length" class="review-images"><img v-for="img in images(r.imagesJson)" :key="img" :src="img"></div><small class="muted">{{new Date(r.createdAt).toLocaleString()}} · 已追评 {{r.appendCount}}/3</small></div></article><el-empty v-if="!reviews.length" description="暂无评价，购买后分享第一条体验吧"/></section></div>
<Teleport to="body"><transition name="buy-modal"><div v-if="addressDialog" class="buy-address-mask" @click.self="addressDialog=false"><section class="buy-address-dialog"><header><div><span>BUY NOW</span><h2>选择收货地址</h2><p>确认地址后即可生成订单</p></div><button aria-label="关闭" @click="addressDialog=false">×</button></header><div class="buy-address-content"><div v-if="addressLoading" class="buy-address-empty">正在加载收货地址…</div><div v-else-if="!addresses.length" class="buy-address-empty"><b>⌖</b><h3>还没有收货地址</h3><p>新增地址后即可继续购买</p><router-link class="btn" :to="`/addresses?new=1&return=${route.fullPath}`">＋ 新增收货地址</router-link></div><template v-else><label v-for="a in addresses" :key="a.id" :class="['buy-address-option',{selected:selectedAddressId===a.id}]"><input v-model="selectedAddressId" type="radio" :value="a.id"><i></i><div><b>{{a.receiverName}} <small>{{a.phone}}</small></b><p>{{fullAddress(a)}}</p></div><em v-if="a.isDefault">默认</em></label><router-link class="manage-address" :to="`/addresses?return=${route.fullPath}`">＋ 管理或新增收货地址</router-link></template></div><footer v-if="addresses.length"><div><span>{{formatSpec(selectedSku?.specJson||'{}')}} × {{quantity}}</span><b>合计 ¥{{total.toFixed(2)}}</b></div><button :disabled="!selectedAddressId||submitting" @click="buyNow">{{submitting?'正在提交…':'确认购买'}}</button></footer></section></div></transition></Teleport></template>
<style scoped>.buy-now{padding:12px 22px;border:1px solid #ea580c;border-radius:99px;background:#fff7ed;color:#c2410c;font-weight:800;cursor:pointer}.buy-address-mask{position:fixed;inset:0;z-index:110;display:grid;place-items:center;padding:20px;background:#43140780;backdrop-filter:blur(4px)}.buy-address-dialog{width:min(650px,100%);max-height:86vh;display:flex;flex-direction:column;overflow:hidden;border-radius:21px;background:#fff;box-shadow:0 28px 80px #43140755}.buy-address-dialog>header{display:flex;justify-content:space-between;padding:22px 25px;border-bottom:1px solid #f1e3d9;background:#fffaf6}.buy-address-dialog>header span{color:#f97316;font-size:9px;letter-spacing:2px;font-weight:900}.buy-address-dialog>header h2{margin:5px 0;font-size:24px}.buy-address-dialog>header p{margin:0;color:#967866;font-size:11px}.buy-address-dialog>header button{width:35px;height:35px;border:0;border-radius:50%;background:#fff0e5;color:#c2410c;font-size:22px;cursor:pointer}.buy-address-content{padding:18px 23px;overflow:auto}.buy-address-option{display:grid;grid-template-columns:22px 1fr auto;gap:12px;align-items:center;margin-bottom:10px;padding:16px;border:1px solid #ead8ca;border-radius:13px;cursor:pointer}.buy-address-option.selected{border-color:#f97316;background:#fff8f2}.buy-address-option>input{position:absolute;opacity:0}.buy-address-option>i{width:19px;height:19px;border:1px solid #d9c0af;border-radius:50%}.buy-address-option.selected>i{border:5px solid #f97316}.buy-address-option b,.buy-address-option p{display:block}.buy-address-option small{margin-left:8px;color:#765744}.buy-address-option p{margin:7px 0 0;color:#765744;font-size:12px}.buy-address-option em{padding:3px 7px;border-radius:99px;background:#ffedd5;color:#c2410c;font-size:9px;font-style:normal}.manage-address{display:block;padding:11px;text-align:center;border:1px dashed #fdba74;border-radius:10px;color:#c2410c;text-decoration:none}.buy-address-empty{min-height:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#967866}.buy-address-empty b{font-size:45px;color:#fdba74}.buy-address-dialog>footer{display:flex;align-items:center;justify-content:space-between;padding:16px 23px;border-top:1px solid #f1e3d9}.buy-address-dialog>footer span,.buy-address-dialog>footer b{display:block}.buy-address-dialog>footer span{color:#967866;font-size:11px}.buy-address-dialog>footer b{margin-top:4px;color:#ea580c}.buy-address-dialog>footer button{padding:12px 23px;border:0;border-radius:99px;background:#f97316;color:#fff;font-weight:800;cursor:pointer}.buy-address-dialog>footer button:disabled{opacity:.5}.buy-modal-enter-active,.buy-modal-leave-active{transition:.2s}.buy-modal-enter-from,.buy-modal-leave-to{opacity:0}@media(max-width:650px){.purchase-row{flex-wrap:wrap}.buy-address-mask{padding:0}.buy-address-dialog{width:100%;height:100%;max-height:100vh;border-radius:0}}</style>
